import OpenAI from 'openai';
import { TranslationError } from './translator.js';

export interface RetryOptions {
  // Total attempts including the first call (default 3).
  maxAttempts?: number;
  // First backoff delay in ms; doubles each attempt (default 500).
  baseDelayMs?: number;
  // Upper bound of the additive random jitter in ms (default 100).
  maxJitterMs?: number;
  // Injectable for tests.
  sleep?: (ms: number) => Promise<void>;
  random?: () => number;
}

const defaultSleep = (ms: number) =>
  new Promise<void>((resolve) => setTimeout(resolve, ms));

// Transport-level failure codes (Node/net, and undici fetch wrappers) that
// never produce an HTTP response: safe to retry like SDK connection errors.
const RETRYABLE_CODES = new Set([
  'ECONNRESET',
  'ECONNREFUSED',
  'ETIMEDOUT',
  'ENOTFOUND',
  'EAI_AGAIN',
  'EHOSTUNREACH',
  'ENETUNREACH',
  'EPIPE',
]);

export function isRetryableError(err: unknown): boolean {
  if (err instanceof TranslationError) return false;
  const status = (err as { status?: unknown })?.status;
  if (typeof status === 'number') {
    return status === 429 || status >= 500;
  }
  // The openai SDK throws APIConnectionError (and its timeout subclass) for
  // DNS/TCP/TLS failures and request timeouts with no HTTP response.
  if (err instanceof OpenAI.APIConnectionError) return true;
  const code = (err as { code?: unknown })?.code;
  if (
    typeof code === 'string' &&
    (RETRYABLE_CODES.has(code) || code.startsWith('UND_ERR'))
  ) {
    return true;
  }
  // fetch() wraps the real transport error in TypeError.cause (undici).
  const cause = (err as { cause?: unknown })?.cause;
  return cause !== undefined && cause !== err && isRetryableError(cause);
}

export async function withRetry<T>(
  fn: () => Promise<T>,
  options: RetryOptions = {},
): Promise<T> {
  const maxAttempts = options.maxAttempts ?? 3;
  const baseDelayMs = options.baseDelayMs ?? 500;
  const maxJitterMs = options.maxJitterMs ?? 100;
  const sleep = options.sleep ?? defaultSleep;
  const random = options.random ?? Math.random;
  for (let attempt = 0; ; attempt++) {
    try {
      return await fn();
    } catch (err) {
      if (attempt + 1 >= maxAttempts || !isRetryableError(err)) {
        throw err;
      }
      await sleep(baseDelayMs * 2 ** attempt + random() * maxJitterMs);
    }
  }
}

