import { describe, expect, it } from 'vitest';
import type OpenAI from 'openai';
import { isRetryableError, withRetry } from './retry.js';
import { OpenAICompatTranslator, type LLMEndpoint } from './openai-compat.js';
import { TranslationError } from './translator.js';

const httpError = (status: number) =>
  Object.assign(new Error(`HTTP ${status}`), { status });

const noSleep = () => Promise.resolve();

describe('isRetryableError', () => {
  it('treats 5xx and 429 as retryable', () => {
    expect(isRetryableError(httpError(500))).toBe(true);
    expect(isRetryableError(httpError(503))).toBe(true);
    expect(isRetryableError(httpError(429))).toBe(true);
  });

  it('treats other 4xx as non-retryable', () => {
    for (const status of [400, 401, 403, 404, 422]) {
      expect(isRetryableError(httpError(status))).toBe(false);
    }
  });

  it('treats transport errors as retryable', () => {
    expect(isRetryableError(Object.assign(new Error('reset'), { code: 'ECONNRESET' }))).toBe(true);
    expect(
      isRetryableError(
        new TypeError('fetch failed', { cause: { code: 'UND_ERR_CONNECT_TIMEOUT' } }),
      ),
    ).toBe(true);
  });

  it('treats TranslationError and plain errors as non-retryable', () => {
    expect(isRetryableError(new TranslationError('empty translation response'))).toBe(false);
    expect(isRetryableError(new Error('boom'))).toBe(false);
  });
});

describe('withRetry', () => {
  it('doubles the base delay each attempt and adds bounded jitter', async () => {
    const delays: number[] = [];
    let calls = 0;
    await expect(
      withRetry(
        async () => {
          calls++;
          throw httpError(500);
        },
        {
          sleep: async (ms) => {
            delays.push(ms);
          },
          random: () => 0.5,
          maxJitterMs: 100,
        },
      ),
    ).rejects.toThrow('HTTP 500');
    expect(calls).toBe(3);
    expect(delays).toEqual([550, 1050]);
  });
});

describe('OpenAICompatTranslator retries', () => {
  const segment = { text: 'How are you?' };
  const endpoint: LLMEndpoint = { baseURL: 'https://p', apiKey: 'k', model: 'm' };

  function scriptedClient(script: Array<'ok' | Error>) {
    const calls: string[] = [];
    const factory = (ep: LLMEndpoint) =>
      ({
        chat: {
          completions: {
            create: async () => {
              calls.push(ep.baseURL);
              const next = script.length > 1 ? script.shift()! : script[0]!;
              if (next instanceof Error) throw next;
              return { choices: [{ message: { content: 'translated' } }] };
            },
          },
        },
      }) as unknown as Pick<OpenAI, 'chat'>;
    return { calls, factory };
  }

  const retry = { sleep: noSleep, random: () => 0 };

  it('retries a 5xx and then succeeds', async () => {
    const { calls, factory } = scriptedClient([httpError(503), 'ok']);
    const t = new OpenAICompatTranslator(endpoint, undefined, factory, retry);
    const out = await t.translate(segment, [], 'vi');
    expect(out).toBe('translated');
    expect(calls).toEqual(['https://p', 'https://p']);
  });

  it('retries a 429 the same way', async () => {
    const { calls, factory } = scriptedClient([httpError(429), 'ok']);
    const t = new OpenAICompatTranslator(endpoint, undefined, factory, retry);
    await expect(t.translate(segment, [], 'vi')).resolves.toBe('translated');
    expect(calls).toHaveLength(2);
  });

  it('fails immediately on a non-retryable 4xx', async () => {
    const { calls, factory } = scriptedClient([httpError(400)]);
    const t = new OpenAICompatTranslator(endpoint, undefined, factory, retry);
    await expect(t.translate(segment, [], 'vi')).rejects.toBeInstanceOf(
      TranslationError,
    );
    expect(calls).toEqual(['https://p']);
  });

  it('does not retry a malformed (empty) response', async () => {
    const calls: string[] = [];
    const factory = (ep: LLMEndpoint) =>
      ({
        chat: {
          completions: {
            create: async () => {
              calls.push(ep.baseURL);
              return { choices: [{ message: { content: '   ' } }] };
            },
          },
        },
      }) as unknown as Pick<OpenAI, 'chat'>;
    const t = new OpenAICompatTranslator(endpoint, undefined, factory, retry);
    await expect(t.translate(segment, [], 'vi')).rejects.toBeInstanceOf(
      TranslationError,
    );
    expect(calls).toEqual(['https://p']);
  });

  it('surfaces the failure after 3 exhausted attempts', async () => {
    const { calls, factory } = scriptedClient([httpError(500)]);
    const t = new OpenAICompatTranslator(endpoint, undefined, factory, retry);
    await expect(t.translate(segment, [], 'vi')).rejects.toBeInstanceOf(
      TranslationError,
    );
    expect(calls).toEqual(['https://p', 'https://p', 'https://p']);
  });

  it('does not retry a successful response', async () => {
    const { calls, factory } = scriptedClient(['ok']);
    const t = new OpenAICompatTranslator(endpoint, undefined, factory, retry);
    await expect(t.translate(segment, [], 'vi')).resolves.toBe('translated');
    expect(calls).toEqual(['https://p']);
  });
});

